use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(p: Vec<string>, i: int) -> int {
    p[i as usize].parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let k = p[0].clone()
        let mut nm = ""
        let mut c = 0
        let mut d = 0
        if k == "square" {
            let s = Square { s: num(p.clone(), 1) }
            nm = "square"
            c = s.corners()
            d = s.double_area()
        } else if k == "rect" {
            let s = Rect { w: num(p.clone(), 1), h: num(p.clone(), 2) }
            nm = "rect"
            c = s.corners()
            d = s.double_area()
        } else if k == "rtri" {
            let s = Rtri { a: num(p.clone(), 1), b: num(p.clone(), 2) }
            nm = "rtri"
            c = s.corners()
            d = s.double_area()
        } else if k == "trap" {
            let s = Trap { a: num(p.clone(), 1), b: num(p.clone(), 2), h: num(p.clone(), 3) }
            nm = "trap"
            c = s.corners()
            d = s.double_area()
        } else {
            continue
        }
        println("{} corners={} area2={}", nm, c, d)
        total = total + d
        if d > best {
            best = d
            best_name = nm
        }
    }
    println("total area2={}", total)
    if best < 0 {
        println("largest=none")
    } else {
        println("largest={} area2={}", best_name, best)
    }
}

